<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { Clock3,Eye,RefreshCw,Search,ShieldCheck,X } from '@lucide/vue'
import { getAdminAuditLog,listAdminAuditLogs } from '@/api/admin/audit'
import type { AdminAuditLog } from '@/api/admin/types'
import { formatDateTime } from '@/lib/format'

const logs=ref<AdminAuditLog[]>([]);const total=ref(0);const page=ref(1);const loading=ref(true);const refreshing=ref(false);const message=ref('');const loadError=ref('');const detail=ref<AdminAuditLog|null>(null);const filters=reactive({q:'',actor_email:'',method:'',success:''})
async function load(background=false){if(background)refreshing.value=true;else loading.value=true;loadError.value='';try{const res=await listAdminAuditLogs({page:page.value,page_size:20,q:filters.q.trim()||undefined,actor_email:filters.actor_email.trim()||undefined,method:filters.method||undefined,success:filters.success||undefined});logs.value=res.items;total.value=res.total}catch(caught){loadError.value=caught instanceof Error&&caught.message?caught.message:'审计日志加载失败'}finally{loading.value=false;refreshing.value=false}}
function search(){page.value=1;void load(true)}async function open(row:AdminAuditLog){detail.value=row;try{detail.value=await getAdminAuditLog(row.id)}catch{message.value='日志详情暂时无法更新'}}function prettyBody(body?:string){if(!body)return'';try{return JSON.stringify(JSON.parse(body),null,2)}catch{return body}}function ok(code:number){return code>=200&&code<400}onMounted(()=>void load())
</script>
<template><div class="audit-page"><header class="page-header drag-region"><div><span>SECURITY AUDIT</span><h1>审计日志</h1><p>追踪管理面操作、认证来源与变更结果。</p></div><button class="refresh no-drag" @click="load(true)"><RefreshCw :size="16" :class="{spinning:refreshing}"/>刷新</button></header>
<section class="audit-banner"><ShieldCheck :size="20"/><div><strong>管理操作留痕已启用</strong><span>凭据与敏感请求字段由服务端脱敏后展示；清理日志需前往网页后台完成 TOTP 验证。</span></div></section>
<form class="filters" data-testid="audit-filters" @submit.prevent="search"><label class="search"><Search :size="15"/><input v-model="filters.q" data-testid="audit-search" placeholder="搜索操作、路径或请求 ID"/></label><input v-model="filters.actor_email" placeholder="操作者邮箱"/><select v-model="filters.method"><option value="">全部方法</option><option>GET</option><option>POST</option><option>PUT</option><option>DELETE</option></select><select v-model="filters.success"><option value="">全部结果</option><option value="true">成功</option><option value="false">失败</option></select><button type="submit">筛选</button></form><p v-if="message" class="message">{{ message }}</p>
<section class="table-wrap"><div v-if="loading" class="loading"><i v-for="n in 7" :key="n"/></div><div v-else-if="loadError" class="empty error-state" data-testid="audit-error"><strong>审计日志加载失败</strong><span>{{ loadError }}</span><button type="button" data-testid="retry-audit" @click="load()">重新加载</button></div><div v-else-if="!logs.length" class="empty" data-testid="audit-empty">暂无符合条件的审计事件</div><div v-else class="table"><div class="row head"><span>时间</span><span>操作者</span><span>操作 / 路径</span><span>结果</span><span>耗时</span><span>来源 IP</span><span>详情</span></div><article v-for="row in logs" :key="row.id" class="row"><span class="time">{{ formatDateTime(row.created_at) }}</span><div><strong>{{ row.actor_email||'—' }}</strong><span>{{ row.actor_role }} · {{ row.auth_method }}</span></div><div class="action"><strong>{{ row.action }}</strong><span><b>{{ row.method }}</b>{{ row.path }}</span></div><span class="status" :class="{failed:!ok(row.status_code)}"><i/>{{ row.status_code }}</span><span>{{ row.latency_ms }} ms</span><span class="mono">{{ row.client_ip||'—' }}</span><button class="view" :data-testid="`audit-log-${row.id}`" @click="open(row)"><Eye :size="15"/></button></article></div></section>
<footer v-if="total>20" class="pagination"><button :disabled="page<=1" @click="page--;load(true)">上一页</button><span>第 {{ page }} 页</span><button :disabled="page*20>=total" @click="page++;load(true)">下一页</button></footer>
<Transition name="drawer"><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><aside data-testid="audit-detail"><header><div><h2>{{ detail.action }}</h2><p>{{ detail.method }} {{ detail.path }}</p></div><button @click="detail=null"><X :size="18"/></button></header><div class="hero"><span class="status" :class="{failed:!ok(detail.status_code)}"><i/>{{ detail.status_code }}</span><strong>{{ formatDateTime(detail.created_at) }}</strong><span><Clock3 :size="14"/>{{ detail.latency_ms }} ms</span></div><section class="cards"><div><span>操作者</span><strong>{{ detail.actor_email }}</strong><em>{{ detail.actor_role }}</em></div><div><span>认证方式</span><strong>{{ detail.auth_method }}</strong><em>{{ detail.credential_masked||'—' }}</em></div><div><span>来源 IP</span><strong>{{ detail.client_ip||'—' }}</strong><em>{{ detail.user_agent||'—' }}</em></div></section><dl><div><dt>请求 ID</dt><dd>{{ detail.request_id||'—' }}</dd></div><div><dt>请求路径</dt><dd>{{ detail.method }} {{ detail.path }}</dd></div></dl><section v-if="detail.request_body" class="body"><h3>脱敏请求体</h3><pre>{{ prettyBody(detail.request_body) }}</pre></section><section v-if="detail.extra" class="body"><h3>附加信息</h3><pre>{{ JSON.stringify(detail.extra,null,2) }}</pre></section></aside></div></Transition>
</div></template>
<style scoped>
