(--border-subtle);border-radius:8px}.hero>strong{font-size:11px}.hero>span:last-child{display:flex;align-items:center;gap:5px;margin-left:auto;color:var(--text-tertiary);font-size:11px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.cards>div{display:grid;gap:5px;padding:12px;background:white;border:1px solid var(--border-subtle);border-radius:7px}.cards span{color:var(--text-tertiary);font-size:9px}.cards strong{overflow:hidden;font-size:11px;text-overflow:ellipsis}.cards em{overflow:hidden;color:var(--text-secondary);font-family:var(--font-data);font-size:9px;font-style:normal;text-overflow:ellipsis}dl{margin-top:12px;background:white;border:1px solid var(--border-subtle);border-radius:8px}dl div{display:flex;min-height:41px;align-items:center;justify-content:space-between;gap:14px;padding:0 11px;border-bottom:1px solid var(--border-subtle)}dl div:last-child{border-bottom:0}dt{color:var(--text-tertiary);font-size:10px}dd{margin:0;font-family:var(--font-data);font-size:10px;overflow-wrap:anywhere;text-align:right}.body h3{margin:20px 0 8px;font-size:12px}.body pre{max-height:300px;padding:13px;overflow:auto;background:#f0f3f7;border-radius:7px;font-size:10px;line-height:1.6;white-space:pre-wrap}.spinning{animation:spin .75s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@container app-content (max-width:900px){.audit-page{padding:24px}.filters{flex-wrap:wrap}.filters .search{flex-basis:100%}.table-wrap{overflow-x:auto}}@container app-content (max-width:680px){.page-header{align-items:flex-start;flex-direction:column;gap:15px}.refresh{width:100%;justify-content:center}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
.error-state{align-content:center;justify-items:center;gap:7px}.error-state strong{color:var(--text-primary);font-size:14px}.error-state button{margin-top:5px;padding:7px 11px;border:0;border-radius:6px;background:var(--accent);color:white}
